const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const damiettaPoint = ee.Geometry.Point([31.492, 31.525]); // Damietta Nile mouth
  const roi = damiettaPoint.buffer(2000); // 2km buffer around the point

  const start1984 = '1984-01-01';
  const end1984 = '1984-12-31';
  const start2021 = '2021-01-01';
  const end2021 = '2021-12-31';

  // Function to calculate NDVI
  const addNDVI = function(image) {
    const ndvi = image.normalizedDifference(['B4', 'B3']).rename('NDVI');
    return image.addBands(ndvi);
  };

  // 2. Data Acquisition for 1984 (Landsat 5)
  let col1984 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterDate(start1984, end1984)
    .filterBounds(roi)
    .map(addNDVI);

  let col1984Size = col1984.size().getInfo();
  console.log(`1984 Images: ${col1984Size}`);

  // Try fallback if no Landsat 5 data
  if (col1984Size === 0) {
    col1984 = ee.ImageCollection('LANDSAT/LT04/C02/T1_L2')
      .filterDate(start1984, end1984)
      .filterBounds(roi)
      .map(addNDVI);
    col1984Size = col1984.size().getInfo();
    console.log(`1984 Images (L4 fallback): ${col1984Size}`);
  }

  if (col1984Size === 0) {
    console.log("No data for 1984.");
    console.log("<answer>C1</answer>");
    return;
  }

  // Data Acquisition for 2021 (Landsat 8)
  let col2021 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterDate(start2021, end2021)
    .filterBounds(roi)
    .map(addNDVI);

  let col2021Size = col2021.size().getInfo();
  console.log(`2021 Images: ${col2021Size}`);

  if (col2021Size === 0) {
    console.log("No data for 2021.");
    console.log("<answer>C1</answer>");
    return;
  }

  // Create median composites
  const composite1984 = col1984.median().select('NDVI');
  const composite2021 = col2021.median().select('NDVI');

  // 3. Check valid pixels
  const stats1984 = composite1984.reduceRegion({
    reducer: ee.Reducer.count().combine({
      reducer2: ee.Reducer.mean(),
      sharedInputs: true
    }),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const stats2021 = composite2021.reduceRegion({
    reducer: ee.Reducer.count().combine({
      reducer2: ee.Reducer.mean(),
      sharedInputs: true
    }),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const count1984 = stats1984.NDVI_count || 0;
  const count2021 = stats2021.NDVI_count || 0;
  const mean1984 = stats1984.NDVI_mean;
  const mean2021 = stats2021.NDVI_mean;

  console.log(`1984: NDVI=${mean1984?.toFixed(3)}, Pixels=${count1984}`);
  console.log(`2021: NDVI=${mean2021?.toFixed(3)}, Pixels=${count2021}`);

  // 4. Validation checks
  if (count1984 === 0 || count2021 === 0) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (mean1984 === null || mean1984 === undefined || 
      mean2021 === null || mean2021 === undefined ||
      isNaN(mean1984) || isNaN(mean2021)) {
    console.log("Calculation failed - invalid NDVI values.");
    console.log("<answer>C3</answer>");
    return;
  }

  // 5. Final comparison
  if (mean1984 > 1 || mean1984 < -1 || mean2021 > 1 || mean2021 < -1) {
    console.log("Invalid NDVI range detected.");
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare vegetation cover (NDVI)
  if (mean1984 > mean2021) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
